1	use std::env;
2	use std::path::Path;
3	use std::path::PathBuf;
4	
5	/// Finds a package's install root: probes `$env_var` first, then each of
6	/// `default_paths`, for any of the `check_files` — several cover layout
7	/// variants like `include/` vs `targets/<arch>/include/`. Returns the
8	/// matched root and check file.
9	///
10	/// # Panics
11	/// When nothing matches.
12	#[cfg(test)]
13	fn find_package(
14	    provider: &str,
15	    env_var: &str,
16	    default_paths: &[&str],
17	    check_files: &[&str],
18	) -> (PathBuf, PathBuf) {
19	    println!("cargo:rerun-if-env-changed={}", env_var);
20	    let env_root = env::var_os(env_var).map(PathBuf::from);
21	    let roots: Vec<PathBuf> = env_root
22	        .clone()
23	        .into_iter()
24	        .chain(default_paths.iter().map(PathBuf::from))
25	        .collect();
26	    for root in &roots {
27	        for check in check_files {
28	            let found = root.join(check);
29	            if found.is_file() {
30	                if let Some(env_root) = &env_root
31	                    && env_root != root
32	                {
33	                    println!(
34	                        "cargo:warning={provider}: ${env_var} ({}) contains none of \
35	                         {check_files:?}; using {} instead",
36	                        env_root.display(),
37	                        root.display()
38	                    );
39	                }
40	                return (root.clone(), found);
41	            }
42	        }
43	    }
44	    panic!(
45	        "{provider} build error: none of {check_files:?} found. \
46	         Looked at `${env_var}` ({env_status}) and default paths {default_paths:?}. \
47	         Hint: install the provider headers or set `{env_var}` to their install root.",
48	        env_status = env_root
49	            .map(|root| format!("set to {root:?}"))
50	            .unwrap_or_else(|| "unset".to_string()),
51	    )
52	}
