54	/// `targets/<dir>` names for the build target; aarch64 toolkits ship as
55	/// either `aarch64-linux` or `sbsa-linux`. Host arch outside build scripts.
56	fn target_dirs() -> Vec<String> {
57	    let arch =
58	        env::var("CARGO_CFG_TARGET_ARCH").unwrap_or_else(|_| std::env::consts::ARCH.to_string());
59	    match arch.as_str() {
60	        "aarch64" => vec!["aarch64-linux".to_string(), "sbsa-linux".to_string()],
61	        arch => vec![format!("{arch}-linux")],
62	    }
63	}
