145	fn existing_deduped(dirs: Vec<PathBuf>) -> Vec<PathBuf> {
146	    let mut seen = Vec::new();
147	    let mut out = Vec::new();
148	    for dir in dirs {
149	        if !dir.is_dir() {
150	            continue;
151	        }
152	        let canon = dir.canonicalize().unwrap_or_else(|_| dir.clone());
153	        if !seen.contains(&canon) {
154	            seen.push(canon);
155	            out.push(dir);
156	        }
157	    }
158	    out
159	}
